WF.theme=function(){const DEFAULTS={"--bg":"#060000","--panel":"#0f151b","--panel-hover":"#161f27","--border":"#23303a","--text":"#e6ecf1","--item-owned":"#1a140c","--item-owned-hover":"#413110","--accent-color":"#bea966"},CSS_VARS=Object.keys(DEFAULTS);function apply(colors){CSS_VARS.forEach((cssVar=>document.documentElement.style.setProperty(cssVar,colors[cssVar]||DEFAULTS[cssVar])))}return{CSS_VARS:CSS_VARS,DEFAULTS:DEFAULTS,apply:apply,init:function(){apply(WF.options.load().themeColors||{})},setColor:function(cssVar,hexValue){const options=WF.options.load(),themeColors={...options.themeColors||{},[cssVar]:hexValue};WF.options.save({...options,themeColors:themeColors}),apply(themeColors)},reset:function(){WF.options.save({...WF.options.load(),themeColors:{}}),apply({})},getColor:function(cssVar){return(WF.options.load().themeColors||{})[cssVar]||DEFAULTS[cssVar]}}}();